/* Rayo Panel prototype — انبار روی دادهٔ واقعی
   مرحلهٔ ۱: When real data is connected (live on rayocafe.ir, ?data=, or JSON files in «داشبورد کنترل»), the inventory tabs
   show the real records through the shared engine (core/js/inventory-engine.js); otherwise they keep the sample data with a hint.
   مرحلهٔ ۲: On live data and inside an admin session of the current panel (same browser tab, sessionStorage rayo_admin_user),
   receipts, waste/authorized consumption, fryer oil changes and whole counts are saved, and receipts/events can be voided,
   through core/js/inventory-write.js — same record shapes and the same protected save as the current panel. */
(function(){
'use strict';
const IC=window.InvControl,E=window.InvEngine,W=window.InvWrite,inv=P.mods.inventory;
const M=()=>IC.state.M,esc=P.esc,fa=P.fa;
const A=x=>Array.isArray(x)?x:[];
const q=(v,d=2)=>v===null||v===undefined||!Number.isFinite(v)?'—':fa(Number(v.toFixed(d)).toLocaleString('en'));
const T=v=>v===null||v===undefined||!Number.isFinite(v)?'—':RT.money(v);

/* ---------- write access (stage 2) ---------- */
const ses=k=>{try{return sessionStorage.getItem(k)||''}catch(_){return ''}};
const allowed=k=>{if(window.AdminAccess)return AdminAccess.has(k);if(!ses('rayo_admin_user'))return false;if(ses('rayo_admin_role')==='owner')return true;let s=null;try{s=JSON.parse(ses('rayo_admin_sections')||'null')}catch(_){}return s==='*'||(Array.isArray(s)&&s.includes(k))};
const live=()=>IC.ready()&&IC.source()==='live';
const canWrite=()=>live()&&allowed('inventory');
const canVoid=()=>canWrite()&&allowed('inventoryEdit');
const whyLocked=()=>!live()?'ثبت فقط روی دادهٔ زنده ممکن است (پنل باز‌شده از rayocafe.ir)':!ses('rayo_admin_user')?'برای ثبت ابتدا وارد شوید':'کاربر شما دسترسی انبار ندارد';

let posCache={key:'',rows:null};
const pos=()=>{const k=E.CAL.today+'|'+(IC.state.raw?.inventory?.meta?.updatedAt||'');if(posCache.key!==k)posCache={key:k,rows:E.positions(M(),E.CAL.today)};return posCache.rows};
const lastSaleDay=()=>{const m=M();let mx=null;for(const s of m.sales)if(mx===null||s.b>mx)mx=s.b;return mx};
const srcLine=()=>`<div class="row" style="gap:8px;margin-bottom:var(--s3);flex-wrap:wrap">${P.b(IC.source()==='live'?'دادهٔ زنده':'دادهٔ واقعی از فایل',IC.source()==='live'?'success':'info')}${canWrite()?P.b('ثبت فعال — '+esc(ses('rayo_admin_user')),'success'):P.b('فقط خواندنی','neutral')}<span class="muted" style="font-size:12px">آخرین تغییر انبار: ${esc(String(IC.state.raw?.inventory?.meta?.updatedAt||'').slice(0,16).replace('T',' '))} · ${canWrite()?'هر ثبت از سرور خوانده، ذخیره و دوباره بازخوانی و مقایسه می‌شود':esc(whyLocked())}</span></div>${W.state.uncertain?P.note('<b>نتیجهٔ آخرین ذخیره تأیید نشد.</b> تا بازخوانی صفحه ثبت جدید ممکن نیست؛ بعد از بازخوانی، وجود ثبت قبلی را در فهرست بررسی کنید.','alert-triangle'):''}`;
const salesGap=()=>{const l=lastSaleDay(),today=E.CAL.i(E.CAL.today);if(l===null)return P.note('<b>هیچ فروشی ثبت نشده است.</b> مصرف رسپی از موجودی کم نمی‌شود.','alert-triangle');const gap=today-l;return gap>2?P.note(`<b>فروش از ${fa(E.CAL.k(l+1))} تا امروز (${fa(gap)} روز) ثبت نشده است.</b> موجودی اقلامی که در این مدت فروش رفته‌اند بیش از واقعیت نشان داده می‌شود؛ فایل فروش این روزها را در «فروش» وارد کنید.`,'alert-triangle'):''};
const FL={negative:['منفی','danger'],noCount:['بدون شمارش','warning'],unapproved:['شمارش تأییدنشده','warning'],countUnit:['واحد شمارش متفاوت','warning']};
const flags=r=>[...r.flags].map(f=>FL[f]?P.b(...FL[f]):'').join(' ');

/* ---------- stock ---------- */
let sQ='',sCat='',sOnly='';
function stockReal(){const rows=pos(),cats=[...new Set(rows.map(r=>r.category).filter(Boolean))].sort(),val=rows.reduce((a,r)=>a+(r.value||0),0);
 return srcLine()+salesGap()+`<div class="grid grid-4">${P.kpi({label:'ارزش موجودی محاسباتی',icon:'boxes',value:RT.money(val),unit:'تومان',foot:`${fa(rows.filter(r=>r.qty!==null).length)} قلم دارای موجودی محاسبه‌شده`})}${P.kpi({label:'موجودی منفی',icon:'trending-down',value:fa(rows.filter(r=>r.flags.has('negative')).length),foot:'ورود ثبت‌نشده، رسپی بیش از واقع یا شمارش ناقص',tone:'danger'})}${P.kpi({label:'هرگز شمرده نشده',icon:'circle-dashed',value:fa(rows.filter(r=>r.flags.has('noCount')).length),tone:'warning'})}${P.kpi({label:'نیازمند سفارش',icon:'refresh-cw',value:fa(rows.filter(r=>r.needOrder).length),foot:'زیر نقطهٔ سفارش'})}</div>
 ${P.card({title:'موجودی اقلام — امروز',sub:'آخرین شمارش هر قلم + ورود − مصرف رسپی فروش − پرتی و مصرف مجاز بعد از آن',flush:1,
  actions:`<input class="input" id="rsQ" placeholder="جستجو" value="${esc(sQ)}" style="width:180px"><select class="select" id="rsCat" style="width:auto"><option value="">همهٔ گروه‌ها</option>${cats.map(c=>`<option ${c===sCat?'selected':''}>${esc(c)}</option>`).join('')}</select><select class="select" id="rsOnly" style="width:auto">${[['','همه'],['flag','دارای هشدار'],['order','نیازمند سفارش'],['neg','منفی']].map(([v,l])=>`<option value="${v}" ${v===sOnly?'selected':''}>${l}</option>`).join('')}</select>`,
  body:'<div id="rsTable"></div>'})}`}
function stockTable(root){const rows=pos().filter(r=>(!sQ||P.match(`${r.name} ${r.code}`,sQ))&&(!sCat||r.category===sCat)&&(sOnly!=='flag'||r.flags.size)&&(sOnly!=='order'||r.needOrder)&&(sOnly!=='neg'||r.flags.has('negative'))).sort((a,b)=>(b.value||0)-(a.value||0));
 P.$('#rsTable',root).innerHTML=P.table(['کالا',{t:'موجودی',n:1},'واحد','آخرین شمارش',{t:'ورود بعد از آن',n:1},{t:'مصرف فروش',n:1},{t:'پرتی و مجاز',n:1},{t:'ارزش',n:1},{t:'نقطهٔ سفارش',n:1},'وضعیت'],
  rows.slice(0,300).map(r=>({attr:`data-rs="${esc(r.id)}" style="cursor:pointer"`,c:[P.cellMain(esc(r.name),`${esc(r.code)} · ${esc(r.category)}`),`<b class="${r.qty<0?'neg':''}">${q(r.qty)}</b>`,esc(r.unit),r.basePt?`${fa(r.basePt.date)} <small class="muted">${r.basePt.boundary==='END'?'شب':'صبح'}</small>`:'—',q(r.receipt),q(r.sales),q(r.waste+r.auth),T(r.value),r.reorderPoint?q(r.reorderPoint):'—',flags(r)+(r.needOrder?' '+P.b('سفارش','info'):'')]})),{empty:'موردی نیست'})+(rows.length>300?`<p class="muted" style="padding:8px">۳۰۰ ردیف اول از ${fa(rows.length)}</p>`:'');RT.icons()}
function stockMount(root){const up=()=>stockTable(root);P.$('#rsQ',root).oninput=e=>{sQ=e.target.value;up()};P.$('#rsCat',root).onchange=e=>{sCat=e.target.value;up()};P.$('#rsOnly',root).onchange=e=>{sOnly=e.target.value;up()};up();
 P.$('#rsTable',root).onclick=e=>{const tr=e.target.closest('[data-rs]');if(tr)ledger(tr.dataset.rs)}}
function ledger(id){const m=M(),r=pos().find(x=>x.id===id);if(!r)return;const from=r.basePt?r.basePt.at:-Infinity,ev=[...m.receipts.filter(x=>x.item===id&&x.day>=from).map(x=>[x.date,'ورود به انبار','+'+q(x.qty,3),esc(x.note||x.by)]),...m.wastes.filter(x=>x.item===id&&x.day>=from).map(x=>[x.date,x.auth?(E.RESP_LABEL.staff):'پرتی','−'+q(x.qty,3),esc(x.reason)])].sort((a,b)=>a[0].localeCompare(b[0]));
 P.modal({title:esc(r.name),size:'wide',body:`${flags(r)}<div class="sum-box mt"><span>موجودی محاسباتی امروز</span><b>${q(r.qty,3)} ${esc(r.unit)}</b></div>${P.table(['تاریخ','رویداد',{t:'مقدار',n:1},'توضیح'],[r.basePt?[fa(r.basePt.date),'آخرین شمارش',q(r.base,3),[...r.basePt.statuses].join('، ')]:['—','بدون شمارش','۰',''],...ev.map(x=>[fa(x[0]),x[1],x[2],x[3]]),['تا امروز','مصرف رسپی فروش','−'+q(r.sales,3),'سهم روزهای بعد از شمارش']])}`})}

/* ---------- receipts / waste / reorder / catalog ---------- */
const DAYS60=()=>E.CAL.i(E.CAL.today)-60;
const voidBtn=(kind,id)=>canVoid()?`<button class="btn btn-ghost btn-sm" data-iwv="${kind}" data-id="${esc(id)}">${P.ic('ban')}ابطال</button>`:'';
function receiptReal(){const m=M(),rows=m.receipts.filter(x=>x.day>=DAYS60()).sort((a,b)=>b.day-a.day||String(b.raw?.createdAt||'').localeCompare(String(a.raw?.createdAt||''))),c=x=>m.costAt(x.item,x.date);
 return srcLine()+`<div class="grid grid-4">${P.kpi({label:'ورود ۶۰ روز اخیر',icon:'package-plus',value:fa(rows.length),unit:'ثبت'})}${P.kpi({label:'ارزش تقریبی',icon:'banknote',value:RT.money(rows.reduce((a,x)=>a+(c(x)||0)*x.qty,0)),unit:'تومان',foot:'با آخرین قیمت خرید هر قلم'})}${P.kpi({label:'بدون قیمت در رسید',icon:'badge-dollar-sign',value:fa(rows.filter(x=>!Number(x.raw?.totalPriceToman)&&!Number(x.raw?.unitCostToman)).length)})}${P.kpi({label:'واحد متفاوت با قلم',icon:'ruler',value:fa(rows.filter(x=>x.unit&&E.UK(x.unit)!==E.UK(m.ing.get(x.item)?.recipeUnit)).length),tone:'warning'})}</div>
 ${P.card({title:'ورودهای ۶۰ روز اخیر',flush:1,body:P.table(['تاریخ','کالا',{t:'مقدار',n:1},'واحد',{t:'ارزش',n:1},'ثبت‌کننده','توضیح',''],rows.slice(0,300).map(x=>{const i=m.ing.get(x.item),bad=x.unit&&E.UK(x.unit)!==E.UK(i?.recipeUnit);return[fa(x.date),esc(i?.name||x.item),q(x.qty,3)+(x.raw?.entryUnitFactor>1?`<small class="muted" style="display:block">${q(Number(x.raw.entryQuantity),3)} ${esc(x.raw.entryUnit)}</small>`:''),`${esc(i?.recipeUnit||'')}${bad?' '+P.b('ثبت با '+esc(x.unit),'warning'):''}`,T((c(x)||0)*x.qty),esc(x.by),esc(x.note),x.raw?.invoiceId?'':voidBtn('receipt',x.id)]}))})}`}
function wasteReal(){const m=M(),rows=m.wastes.filter(x=>x.day>=DAYS60()).sort((a,b)=>b.day-a.day),val=x=>(m.costAt(x.item,x.date)||0)*x.qty,seen=new Set;
 return srcLine()+`<div class="grid grid-4">${P.kpi({label:'پرتی ۶۰ روز اخیر',icon:'trash-2',value:RT.money(rows.filter(x=>!x.auth).reduce((a,x)=>a+val(x),0)),unit:'تومان',foot:`${fa(rows.filter(x=>!x.auth).length)} ثبت`})}${P.kpi({label:'مصرف مجاز',icon:'utensils',value:RT.money(rows.filter(x=>x.auth).reduce((a,x)=>a+val(x),0)),unit:'تومان',foot:'پرسنل، تعویض روغن، سر میز'})}${P.kpi({label:'مشکوک به خطای واحد',icon:'scale',value:fa(rows.filter(x=>!x.auth&&/^(kg|l)$/.test(E.UK(m.ing.get(x.item)?.recipeUnit))&&x.qty>=20).length),tone:'danger',foot:'اصلاح دسته‌ای در پنل فعلی: گزارش‌ها ← پرتی'})}${P.kpi({label:'روند و مسئولیت',icon:'chart-column',value:'گزارش‌ها',foot:'انبار ← گزارش‌ها ← پرتی و ضایعات'})}</div>
 ${P.card({title:'ثبت‌های پرتی و مصرف مجاز — ۶۰ روز اخیر',flush:1,body:P.table(['تاریخ','کالا',{t:'مقدار',n:1},'واحد','نوع','علت',{t:'ارزش',n:1},'ثبت‌کننده',''],rows.slice(0,300).map(x=>{const i=m.ing.get(x.item),first=!seen.has(x.id);seen.add(x.id);return[fa(x.date),esc(i?.name||x.item)+(x.fromMenu?`<small class="muted" style="display:block">از ${esc(x.fromMenu)}</small>`:''),q(x.qty,3),esc(i?.recipeUnit||''),x.auth?P.b(x.eventType==='FRYER_OIL_CHANGE'?'تعویض روغن':x.eventType==='TABLE_SERVICE'?'سر میز':'مصرف مجاز','info'):P.b(E.RESP_LABEL[E.responsibility(x)],E.responsibility(x)==='negligence'?'danger':'warning'),`<span class="wrap">${esc(x.reason)}</span>`,T(val(x)),esc(x.by),first?voidBtn('event',x.id):'']}))})}`}
const voidMount=root=>(P.$('#pnTab',root)||root).addEventListener('click',e=>{const b=e.target.closest('[data-iwv]');if(b)voidForm(b.dataset.iwv,b.dataset.id)});
function reorderReal(){const rows=pos().filter(r=>r.hasReorderPoint).sort((a,b)=>(a.qty??0)/a.reorderPoint-(b.qty??0)/b.reorderPoint);
 return srcLine()+salesGap()+P.card({title:'اقلام دارای نقطهٔ سفارش',sub:'موجودی محاسباتی امروز در برابر نقطهٔ سفارش و موجودی هدف',flush:1,body:P.table(['کالا',{t:'موجودی',n:1},{t:'نقطهٔ سفارش',n:1},{t:'هدف',n:1},{t:'پیشنهاد سفارش',n:1},'وضعیت'],rows.map(r=>[esc(r.name),q(r.qty),q(r.reorderPoint),q(r.target),r.needOrder?`<b>${q(Math.max(0,r.target-(r.qty||0)))} ${esc(r.unit)}</b>`:'—',r.needOrder?P.b('نیازمند سفارش','danger'):P.b('کافی','success')]),{empty:'برای هیچ قلمی نقطهٔ سفارش تعریف نشده است'})})+P.note(`فقط ${fa(rows.length)} قلم نقطهٔ سفارش دارند. پیشنهاد: برای اقلام پرمصرف نقطهٔ سفارش را در «تنظیمات انبار» تعریف کنید.`,'info')}
function catalogReal(){const m=M(),rows=[...m.ing.values()].sort((a,b)=>String(a.name).localeCompare(String(b.name),'fa'));
 return srcLine()+P.card({title:'کاتالوگ کالاها و مواد',sub:'مرجع اصلی (pricing.ingredients)',flush:1,body:P.table(['کد','نام','گروه','نوع','واحد مصرف','واحد خرید',{t:'مقدار بسته',n:1},{t:'آخرین قیمت خرید',n:1},'وضعیت'],rows.slice(0,700).map(i=>[esc(i.code),esc(i.name),esc(i.category),esc(i.itemType||''),esc(i.recipeUnit),esc(i.purchaseUnit),q(Number(i.packageQuantity),3),Number(i.lastPurchasePriceToman)>1?P.t(Number(i.lastPurchasePriceToman)):P.b('بدون قیمت','warning'),i.status==='غیرفعال'?P.b('غیرفعال','neutral'):P.b('فعال','success')]))})}

/* ---------- entry forms (stage 2) ---------- */
const raw=()=>IC.state.raw;
const io={
 load:async()=>{const r=await fetch(E.API_ROOT+'Load?module=inventory&_='+Date.now(),{cache:'no-store',credentials:'omit',headers:{Accept:'application/json'}});if(!r.ok)throw Error(`دریافت انبار از سرور: HTTP ${r.status}`);return E.unwrap(await r.json())},
 save:async doc=>{const r=await fetch(E.API_ROOT+'Save?module=inventory',{method:'POST',credentials:'omit',headers:{'Content-Type':'application/json; charset=utf-8',Accept:'application/json, text/plain, */*'},body:JSON.stringify(doc)});if(!r.ok)throw Error(`ذخیره روی سرور: HTTP ${r.status} ${(await r.text()).slice(0,200)}`)},
 actor:()=>ses('rayo_admin_user'),pricing:()=>raw().pricing};
// shared by menu-real.js: io (module) and apply(doc) default to the inventory module
async function run(btn,{action,details,mutate,done,io:mio=io,ioOpts,apply=doc=>IC.attach({...raw(),inventory:doc,source:'live'})}){const label=btn.innerHTML;btn.disabled=true;btn.innerHTML=P.ic('loader')+'ذخیره و تأیید روی سرور…';RT.icons();
 try{const {out,doc}=await W.edit(ioOpts?{...mio,...ioOpts}:mio,{action,details,mutate});apply(doc);P.close();P.render();P.toast(done(out)+(out&&out.recalculated?` — مغایرت ${fa(out.recalculated)} ردیف در شمارش‌های بعدی بازمحاسبه شد`:''),'check')}
 catch(e){const el=document.getElementById('iwErr');if(el)el.textContent=e.message||String(e);P.toast(e.message||String(e),'alert-triangle');if(W.state.uncertain){P.close();P.render()}}
 finally{if(document.body.contains(btn)){btn.disabled=false;btn.innerHTML=label;RT.icons()}}}
function formModal({title,body,ok='ذخیره',size='',onMount,onSave,can=canWrite,why=whyLocked}){
 P.modal({title,size,body:`<form id="iwForm" class="stack" style="gap:var(--s4)" onsubmit="return false">${body}<div id="iwErr" class="neg" role="alert" style="font-size:13px"></div></form>`,
  foot:`<button class="btn btn-ghost" data-close>انصراف</button><button class="btn btn-primary" id="iwOk">${P.ic('check')}${ok}</button>`,
  onMount:m=>{onMount&&onMount(m);const b=P.$('#iwOk',m);b.onclick=e=>{e.preventDefault();P.$('#iwErr',m).textContent='';if(!can())return P.$('#iwErr',m).textContent=why();try{onSave(m,b)}catch(err){P.$('#iwErr',m).textContent=err.message}}}})}
const val=(m,n)=>P.$(`[name=${n}]`,m)?.value??'';
const dateField=(label='تاریخ')=>P.field(label,`<input class="input num" name="date" value="${fa(E.CAL.today)}" placeholder="۱۴۰۵/۰۸/۱۷">`);
const shiftField=()=>P.field('شیفت',`<select class="select" name="shift">${W.SHIFTS.map(s=>`<option>${s}</option>`).join('')}</select>`);
const itemLabel=i=>`${i.name}${i.code?' — '+i.code:''}`;
const stockList=()=>[...M().ing.values()].filter(W.stockItem).sort((a,b)=>String(a.name).localeCompare(String(b.name),'fa'));
const menuList=()=>[...M().menu.values()].filter(x=>x.status!=='غیرفعال').sort((a,b)=>String(a.name).localeCompare(String(b.name),'fa'));
const dataList=(id,list)=>`<datalist id="${id}">${list.map(i=>`<option value="${esc(itemLabel(i))}"></option>`).join('')}</datalist>`;
const latin=s=>String(s).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d));
const pick=(v,list)=>{v=String(v||'').trim();return list.find(i=>itemLabel(i)===v)||list.find(i=>i.name===v)||list.find(i=>i.code&&String(i.code)===latin(v))||null};
const unitOpts=i=>i?W.unitsOf(i).map(u=>`<option value="${esc(u.name)}">${esc(u.name)}${u.factor!==1?` (${fa(u.factor)} ${esc(W.unitName(i))})`:''}</option>`).join(''):'';

function receiptForm(){const list=stockList(),row=()=>`<div class="iw-row"><input class="input" list="iwItems" data-f="item" placeholder="نام یا کد کالا" aria-label="کالا"><input class="input num" data-f="qty" inputmode="decimal" placeholder="مقدار" aria-label="مقدار"><select class="select" data-f="unit" aria-label="واحد"></select><input class="input" data-f="note" placeholder="توضیح (اختیاری)" aria-label="توضیح"><button type="button" class="btn btn-ghost btn-sm btn-icon" data-del aria-label="حذف ردیف">${P.ic('x')}</button></div>`;
 formModal({title:'ثبت ورود به انبار',size:'wide',ok:'ذخیره روی سرور',body:`${dataList('iwItems',list)}<div class="form-grid">${dateField('تاریخ ورود')}</div><div id="iwRows" class="stack" style="gap:8px">${row()}${row()}${row()}</div><button type="button" class="btn btn-ghost btn-sm" id="iwAdd" style="align-self:flex-start">${P.ic('plus')}ردیف جدید</button>${P.note('ورود بدون قیمت ثبت می‌شود، مثل «ورود به انبار» پنل فعلی. قیمت خرید از فاکتور و قیمت‌گذاری می‌آید. مقدار به واحد خرید (مثلاً کارتن) خودکار به واحد انبار تبدیل می‌شود.','info')}`,
  onMount:m=>{const rows=P.$('#iwRows',m);P.$('#iwAdd',m).onclick=()=>{rows.insertAdjacentHTML('beforeend',row());RT.icons()};rows.addEventListener('click',e=>{const b=e.target.closest('[data-del]');if(b&&rows.children.length>1)b.closest('.iw-row').remove()});rows.addEventListener('change',e=>{if(e.target.dataset.f==='item')e.target.closest('.iw-row').querySelector('[data-f=unit]').innerHTML=unitOpts(pick(e.target.value,list))})},
  onSave:(m,btn)=>{const date=E.D(val(m,'date')),lines=[...m.querySelectorAll('.iw-row')].map(r=>({v:r.querySelector('[data-f=item]').value.trim(),q:r.querySelector('[data-f=qty]').value.trim(),u:r.querySelector('[data-f=unit]').value,n:r.querySelector('[data-f=note]').value})).filter(x=>x.v||x.q).map((x,k)=>{const i=pick(x.v,list);if(!i)throw Error(`ردیف ${fa(k+1)}: کالا را از فهرست انتخاب کنید`);return{itemId:i.id,quantity:x.q,unit:x.u,note:x.n}});
   if(!lines.length)throw Error('حداقل یک ردیف وارد کنید');const warn=W.receiptWarnings(raw().inventory,raw().pricing,date,W.receiptLines(raw().pricing,lines));if(warn.length&&!confirm(warn.join('\n')+'\n\nبا همین مقادیر ذخیره شود؟'))return;
   run(btn,{action:'RECEIPT_BATCH_ADDED',details:{date,lines:lines.length},mutate:(d,c)=>W.addReceipts(d,c,{date,lines}),done:o=>`${fa(o.count)} ورود ثبت و روی سرور تأیید شد`})}})}

function eventForm(){const ings=stockList(),menus=menuList(),types=Object.entries(W.EVENT_LABELS).filter(([k])=>k!=='FRYER_OIL_CHANGE');
 formModal({title:'ثبت پرتی یا مصرف مجاز',ok:'ذخیره روی سرور',body:`${dataList('iwIng',ings)}${dataList('iwMenu',menus)}
  <div class="form-grid">${dateField()}${P.field('نوع رویداد',`<select class="select" name="type">${types.map(([k,l])=>`<option value="${k}">${esc(l)}</option>`).join('')}</select>`)}${P.field('نوع مورد','<select class="select" name="kind"><option value="ingredient">مادهٔ اولیه</option><option value="menu">آیتم منو (کسر طبق رسپی)</option></select>')}${shiftField()}</div>
  <div class="form-grid">${P.field('مورد','<input class="input" name="item" list="iwIng" placeholder="نام یا کد">')}${P.field('مقدار','<input class="input num" name="qty" inputmode="decimal">')}${P.field('واحد','<select class="select" name="unit"></select>')}</div>
  ${P.field('علت','<input class="input" name="reason" placeholder="مثلاً سوختگی، تاریخ‌گذشته، افتادن">')}${P.field('توضیح','<textarea class="textarea" name="notes" rows="2"></textarea>')}${P.note('ثبت مدیر «تأییدشده» ذخیره می‌شود. جریمهٔ پرسنل و خرابی اموال از پنل فعلی ثبت می‌شوند.','info')}`,
  onMount:m=>{const k=P.$('[name=kind]',m),it=P.$('[name=item]',m),u=P.$('[name=unit]',m);k.onchange=()=>{const menu=k.value==='menu';it.setAttribute('list',menu?'iwMenu':'iwIng');it.value='';u.innerHTML=menu?'<option>عدد</option>':''};it.onchange=()=>{if(k.value!=='menu')u.innerHTML=unitOpts(pick(it.value,ings))}},
  onSave:(m,btn)=>{const menu=val(m,'kind')==='menu',x=pick(val(m,'item'),menu?menus:ings);if(!x)throw Error('مورد را از فهرست انتخاب کنید');const input={date:E.D(val(m,'date')),eventType:val(m,'type'),type:menu?'menu':'ingredient',itemId:x.id,quantity:val(m,'qty'),unit:val(m,'unit'),shift:val(m,'shift'),reason:val(m,'reason'),notes:val(m,'notes')};
   run(btn,{action:'INVENTORY_EVENT_ADDED',details:{eventType:input.eventType,type:input.type,itemId:x.id,date:input.date},mutate:(d,c)=>W.addEvent(d,c,input),done:r=>`${W.EVENT_LABELS[r.eventType]} «${x.name}» ثبت و تأیید شد`})}})}

function oilForm(){const s=W.oilSettings(raw().inventory,raw().pricing),oil=M().ing.get(s.ingredientId);
 formModal({title:'ثبت تعویض روغن سرخ‌کن',ok:'ذخیره روی سرور',body:`${oil?'':P.note('قلم «روغن سرخ‌کردنی» در تنظیمات انبار مشخص نیست؛ ابتدا در پنل فعلی (انبار ← تنظیمات ← سرخ‌کن‌ها) تعیین کنید.','alert-triangle')}
  <div class="form-grid">${dateField()}${P.field('سرخ‌کن',`<select class="select" name="fryer">${s.fryers.map(f=>`<option value="${esc(f.id)}">${esc(f.name)} — ${fa(f.liters)} لیتر</option>`).join('')}</select>`)}${P.field('نوع','<select class="select" name="kind"><option value="FULL">تعویض کامل</option><option value="TOP_UP">افزودن روغن</option></select>')}${P.field('لیتر','<input class="input num" name="liters" inputmode="decimal">','تعویض کامل: خالی = گنجایش سرخ‌کن')}${shiftField()}</div>
  ${P.field('توضیح','<textarea class="textarea" name="notes" rows="2"></textarea>')}${P.note(`هر لیتر ${fa(s.density)} کیلو حساب می‌شود و به‌عنوان «مصرف مجاز — تعویض روغن» از «${esc(oil?.name||'روغن سرخ‌کردنی')}» کم می‌شود.${s.logFrom?` از ${fa(s.logFrom)} روغن سرخ‌کن از رسپی کم نمی‌شود.`:''}`,'info')}`,
  onSave:(m,btn)=>{const input={date:E.D(val(m,'date')),fryerId:val(m,'fryer'),kind:val(m,'kind'),liters:val(m,'liters'),shift:val(m,'shift'),notes:val(m,'notes')};
   run(btn,{action:'FRYER_OIL_CHANGE_ADDED',details:{fryerId:input.fryerId,kind:input.kind,date:input.date},mutate:(d,c)=>W.addOilChange(d,c,input),done:r=>`${r.reason} ثبت شد (${fa(r.quantity)} کیلو)`})}})}

function countForm(){const list=stockList(),vals=new Map,units=new Map,cats=[...new Set(list.map(i=>i.category).filter(Boolean))].sort();let qf='',cat='',info=null;
 formModal({title:'ثبت شمارش موجودی (پایان روز)',size:'wide',ok:'ذخیره روی سرور',body:`<div class="form-grid">${dateField('تاریخ شمارش')}${P.field('یادداشت','<input class="input" name="note" placeholder="مثلاً شمارش هفتگی">')}</div>
  <div id="iwInfo"></div><div class="row" style="gap:8px;flex-wrap:wrap;align-items:center"><input class="input" id="iwQ" placeholder="جستجوی کالا" style="width:200px"><select class="select" id="iwCat" style="width:auto"><option value="">همهٔ گروه‌ها</option>${cats.map(c=>`<option>${esc(c)}</option>`).join('')}</select><span class="muted" id="iwN"></span></div>
  <div id="iwList" style="max-height:50vh;overflow:auto"></div>${P.note('شمارش کور: موجودی محاسباتی نمایش داده نمی‌شود. فقط اقلامی که مقدار دارند ثبت می‌شوند و بقیه از شمارش قبلی خودشان ادامه می‌دهند. مقدار صفر یعنی «شمرده شد و نیست».','info')}`,
  onMount:m=>{const L=P.$('#iwList',m),N=P.$('#iwN',m);
   const showInfo=()=>{const d=E.D(val(m,'date'));info=d&&E.CAL.i(d)!==null?W.countInfo(raw().inventory,d):null;P.$('#iwInfo',m).innerHTML=!info?'':info.later.length?P.note(`<b>بعد از این تاریخ ${fa(new Set(info.later.map(s=>s.date)).size)} شمارش کل ثبت شده است</b> (آخرین: ${fa([...new Set(info.later.map(s=>s.date))].sort().pop())}). ثبت با تاریخ قبلی ممکن است و مغایرت شمارش‌های بعدی خودکار بازمحاسبه می‌شود (مقدار قبلی در سابقهٔ همان شمارش می‌ماند).`,'alert-triangle'):info.counted.size?P.note(`در این تاریخ ${fa(info.counted.size)} قلم قبلاً شمرده شده است؛ مقدار جدید جایگزین می‌شود و مقدار قبلی در سابقهٔ شمارش می‌ماند.`,'info'):'';draw()};
   const draw=()=>{const rows=list.filter(i=>(!cat||i.category===cat)&&(!qf||P.match(`${i.name} ${i.code}`,qf)));
    L.innerHTML=P.table(['کالا','گروه',{t:'مقدار شمارش',n:1},'واحد'],rows.slice(0,400).map(i=>{const prev=info?.counted.get(i.id)?.line;return[P.cellMain(esc(i.name),esc(i.code||'')),esc(i.category||''),`<input class="input num" style="width:110px" data-c="${esc(i.id)}" inputmode="decimal" value="${esc(vals.get(i.id)||'')}" placeholder="${prev?'قبلی: '+q(Number(prev.actual),3):''}" aria-label="شمارش ${esc(i.name)}">`,`<select class="select" style="width:auto" data-u="${esc(i.id)}">${unitOpts(i).replace(`value="${esc(units.get(i.id)||'')}"`,`value="${esc(units.get(i.id)||'')}" selected`)}</select>`]}),{empty:'موردی پیدا نشد'})+(rows.length>400?`<p class="muted" style="padding:8px">۴۰۰ ردیف اول؛ جستجو را دقیق‌تر کنید</p>`:'');count()};
   const count=()=>{N.textContent=`${fa([...vals.values()].filter(v=>v!=='').length)} قلم وارد شده`};
   L.addEventListener('input',e=>{const id=e.target.dataset.c;if(id){vals.set(id,e.target.value.trim());count()}});L.addEventListener('change',e=>{const id=e.target.dataset.u;if(id)units.set(id,e.target.value)});
   P.$('#iwQ',m).oninput=e=>{qf=e.target.value;draw()};P.$('#iwCat',m).onchange=e=>{cat=e.target.value;draw()};P.$('[name=date]',m).onchange=showInfo;showInfo()},
  onSave:(m,btn)=>{const date=E.D(val(m,'date')),entries=[...vals].filter(([,v])=>v!=='').map(([id,v])=>({itemId:id,quantity:v,unit:units.get(id)||''}));if(!entries.length)throw Error('حداقل یک مقدار شمارش وارد کنید');
   const later=W.countInfo(raw().inventory,date).later,ld=[...new Set(later.map(s=>s.date))];
   if(!confirm(`شمارش ${fa(entries.length)} قلم برای پایان روز ${fa(date)} ذخیره شود؟${ld.length?`\n\nبعد از این تاریخ ${fa(ld.length)} شمارش کل ثبت شده است (${fa([...ld].sort().pop())}). ثبت شمارش با تاریخ قبلی توصیه نمی‌شود؛ مغایرت شمارش‌های بعدی خودکار بازمحاسبه می‌شود.`:''}`))return;
   run(btn,{action:'WHOLE_COUNT_SAVED',details:{date,lines:entries.length,...(ld.length?{earlierThanLaterCounts:ld.length}:{})},mutate:(d,c)=>W.addCount(d,c,{date,entries,note:val(m,'note'),allowEarlier:ld.length>0}),done:o=>`شمارش ${fa(o.count)} قلم ثبت شد${o.replaced?` (${fa(o.replaced)} قلم جایگزین شد)`:''}`})}})}

function voidForm(kind,id){const doc=raw().inventory,r=kind==='receipt'?A(doc.stockReceipts).find(x=>x.id===id):W.findEvent(doc,id);if(!r)return;const i=M().ing.get(r.ingredientId||r.itemId)||M().menu.get(r.itemId);
 formModal({title:kind==='receipt'?'ابطال ورود انبار':'ابطال ثبت پرتی / مصرف',ok:'ابطال روی سرور',body:`<div class="sum-box"><span>${esc(i?.name||r.itemNameSnapshot||'—')} · ${fa(r.date)}${r.eventType?' · '+esc(W.EVENT_LABELS[r.eventType]||r.eventType):''}</span><b>${q(Number(r.quantity),3)} ${esc(r.unitSnapshot||(r.type==='menu'?'عدد':i?.recipeUnit)||'')}</b></div>${P.field('علت ابطال *','<textarea class="textarea" name="reason" rows="2"></textarea>')}${P.note('رکورد حذف نمی‌شود: وضعیتش «باطل» می‌شود و نسخهٔ قبل از ابطال با نام شما در سابقه می‌ماند. مغایرت شمارش‌های بعدی در ذخیرهٔ بعدی پنل فعلی یا با «بازمحاسبه همه» به‌روز می‌شود.','info')}`,
  onSave:(m,btn)=>{const reason=val(m,'reason');if(!canVoid())throw Error('ابطال فقط برای کاربر دارای دسترسی «ویرایش، ابطال و بازگردانی ثبت‌های انبار» مجاز است');
   run(btn,{action:kind==='receipt'?'RECEIPT_VOIDED':'INVENTORY_EVENT_VOIDED',details:{entityId:id,reason},mutate:(d,c)=>kind==='receipt'?W.voidReceipt(d,c,{id,reason}):W.voidEvent(d,c,{id,reason}),done:()=>'ابطال ثبت و روی سرور تأیید شد'})}})}
/* ---------- sales from Excel (stage 11, core/js/sales-write.js) ---------- */
const SW=window.SalesWrite;
const ioMod=(module,validate)=>({module,validate,actor:()=>ses('rayo_admin_user'),pricing:()=>raw().pricing,
 load:async()=>{const r=await fetch(E.API_ROOT+`Load?module=${module}&_=`+Date.now(),{cache:'no-store',credentials:'omit',headers:{Accept:'application/json'}});if(!r.ok)throw Error(`دریافت ${module} از سرور: HTTP ${r.status}`);return E.unwrap(await r.json())},
 save:async doc=>{const r=await fetch(E.API_ROOT+`Save?module=${module}`,{method:'POST',credentials:'omit',headers:{'Content-Type':'application/json; charset=utf-8',Accept:'application/json, text/plain, */*'},body:JSON.stringify(doc)});if(!r.ok)throw Error(`ذخیره روی سرور: HTTP ${r.status} ${(await r.text()).slice(0,200)}`)}});
const ioPricing=ioMod('pricing',d=>!!d&&Array.isArray(d.menuItems)&&Array.isArray(d.ingredients)&&Array.isArray(d.recipes));
let salesForm={source:'SEPIDZ',from:'',to:'',reference:''},salesPrev=null;
function salesReal(){const f=salesForm,t=fa(E.CAL.today),rows=A(raw().inventory.salesPeriods).filter(x=>!x.isArchived).slice().sort((a,b)=>String(b.to||b.date||b.from).localeCompare(String(a.to||a.date||a.from))||String(b.createdAt).localeCompare(String(a.createdAt))),menu=M().menu;
 return srcLine()+salesGap()+P.card({title:'ثبت فروش از فایل Excel',sub:'منبع و بازه را انتخاب کنید و فایل «تعداد فروش کالا» را وارد کنید؛ بازه می‌تواند یک روز، یک هفته، یک ماه یا چند روز باشد',body:`<div class="form-grid">${P.field('منبع فروش',`<select class="select" id="slSrc">${SW.SOURCES.map(([k,l])=>`<option value="${k}" ${k===f.source?'selected':''}>${l}</option>`).join('')}</select>`)}${P.field('از تاریخ',`<input class="input num" id="slFrom" value="${f.from?fa(f.from):t}">`)}${P.field('تا تاریخ',`<input class="input num" id="slTo" value="${f.to?fa(f.to):t}">`)}${P.field('مرجع / توضیح',`<input class="input" id="slRef" value="${esc(f.reference)}" placeholder="اختیاری؛ مثلاً مهر ۱۴۰۵">`)}</div>
  <div class="row mt" style="gap:8px;flex-wrap:wrap;align-items:center">${canWrite()?`<button class="btn btn-primary" id="slPick">${P.ic('file-spreadsheet')}انتخاب فایل Excel و پیش‌نمایش</button>`:`<button class="btn btn-secondary" disabled title="${esc(whyLocked())}">${P.ic('lock')}انتخاب فایل Excel</button>`}<input type="file" id="slFile" accept=".xlsx,.xls,.csv" hidden><span class="muted" style="font-size:12px">ستون‌های لازم: «کد کالا»، «نام کالا» و «تعداد». با ستون «تاریخ» هر روز جدا ثبت می‌شود. قبل از ثبت، پیش‌نمایش و ردیف‌های نامطابق نمایش داده می‌شود.</span></div>`})
 +`<div class="mt">${P.card({title:'سوابق فروش ثبت‌شده',flush:1,body:P.table(['منبع','دوره','مرجع',{t:'آیتم',n:1},{t:'تعداد فروش',n:1},{t:'مبلغ',n:1},'ثبت','وضعیت',''],rows.map(sp=>{const a=sp.from||sp.date,b=sp.to||sp.date||a,q=A(sp.lines).reduce((s,l)=>s+Number(l.quantity||0),0),rev=A(sp.lines).reduce((s,l)=>s+(Number(l.saleAmountToman)||Number(l.quantity||0)*Number(l.salePriceToman||menu.get(l.menuItemId)?.currentPriceToman||0)),0);return[esc(SW.sourceLabel(SW.sourceOf(sp))),`${fa(E.D(a))}${E.D(b)!==E.D(a)?' تا '+fa(E.D(b)):''}`,esc(sp.reference||'—'),fa(A(sp.lines).length),fa(Math.round(q)),T(rev),esc(sp.createdBy||''),sp.status==='void'?P.b('ابطال‌شده','danger'):P.b('ثبت','success',1),sp.status!=='void'&&canVoid()?`<button class="btn btn-ghost btn-sm" data-slv="${esc(sp.id)}">${P.ic('ban')}ابطال</button>`:'']}),{empty:'فروشی ثبت نشده است'})})}</div><div class="mt" id="rvHost"></div>`}
function salesMount(root){IC.render('sales',P.$('#rvHost',root),()=>P.go('#/inventory/reports'));const pick=P.$('#slPick',root),file=P.$('#slFile',root);
 const read=()=>{salesForm={source:P.$('#slSrc',root).value,from:E.D(P.$('#slFrom',root).value),to:E.D(P.$('#slTo',root).value),reference:P.$('#slRef',root).value.trim()};return salesForm};
 if(pick)pick.onclick=()=>{const f=read();if(!f.from||!f.to||E.CAL.i(f.from)===null||E.CAL.i(f.to)===null)return P.toast('از تاریخ و تا تاریخ را به‌صورت ۱۴۰۵/۰۷/۰۱ وارد کنید','alert-triangle');if(f.from>f.to)return P.toast('«از تاریخ» نمی‌تواند بعد از «تا تاریخ» باشد','alert-triangle');file.click()};
 if(file)file.onchange=async e=>{const fl=e.target.files?.[0];e.target.value='';if(!fl)return;try{P.toast('در حال خواندن فایل…','loader');const t=await SW.readFile(fl),f={...read()},p=SW.build(t,fl.name,f,{inventory:raw().inventory,pricing:raw().pricing});if(p.newItems.length){let list=null;try{list=await SW.onlineMenu();p.onlineStatus='ok'}catch(_){p.onlineStatus='error'}SW.suggest(p,list,raw().pricing)}salesPrev=p;salesPreview(p)}catch(err){P.toast(err.message||'خواندن فایل فروش انجام نشد','alert-triangle')}};
 (P.$('#pnTab',root)||root).addEventListener('click',e=>{const b=e.target.closest('[data-slv]');if(b)voidSalesForm(b.dataset.slv)})}
function salesPreview(p){const menu=M().menu,lines=p.periods.flatMap(x=>x.lines.map(l=>({...l,from:x.from,to:x.to}))),qty=lines.reduce((a,l)=>a+l.quantity,0),amt=lines.reduce((a,l)=>a+l.saleAmountToman,0),conf=p.periods.filter(x=>x.conflicts.length),cats=SW.categories(raw().pricing),blocked=(!p.periods.length&&!p.newItems.some(x=>!x.conflict))||conf.length;
 formModal({title:'پیش‌نمایش ورود فروش از Excel',size:'wide',ok:blocked?'ثبت ممکن نیست':(p.newItems.length?'افزودن آیتم‌های تیک‌خورده و ثبت فروش':`ثبت ${fa(lines.length)} آیتم`),body:`<div class="grid grid-4">${P.kpi({label:'منبع و بازه',icon:'calendar-range',value:esc(SW.sourceLabel(p.source)),foot:p.from===p.to?fa(p.from):`${fa(p.from)} تا ${fa(p.to)}`})}${P.kpi({label:'آیتم مطابق',icon:'check',value:fa(lines.length)})}${P.kpi({label:'جمع تعداد',icon:'hash',value:fa(Math.round(qty))})}${P.kpi({label:'مبلغ',icon:'banknote',value:RT.money(amt),unit:'تومان'})}</div>
  <p class="muted">فایل ${esc(p.fileName)} — ${fa(p.rows)} ردیف${p.zero?`، ${fa(p.zero)} ردیف با تعداد صفر نادیده گرفته شد`:''}${p.hasDate?`، ثبت روزبه‌روز در ${fa(p.periods.length)} روز`:'، ثبت یکجا برای کل بازه'}. مصرف رسپی فروش بازه به‌طور مساوی روی روزهای آن پخش می‌شود.</p>
  ${conf.length?P.note(`<b>ثبت ممکن نیست:</b> برای ${conf.map(x=>x.from===x.to?fa(x.from):`${fa(x.from)} تا ${fa(x.to)}`).join('، ')} فروش ${esc(SW.sourceLabel(p.source))} قبلاً ثبت شده است. ابتدا سند قبلی را از «سوابق فروش» ابطال کنید.`,'alert-triangle'):''}${p.warnings.map(w=>P.note(esc(w),'info')).join('')}
  ${p.unmatched.length?`<h3>ردیف‌های نامطابق — ثبت نمی‌شوند (${fa(p.unmatched.length)})</h3>${P.table(['کد','نام',{t:'تعداد',n:1},'علت'],p.unmatched.map(u=>[esc(u.code),esc(u.name),q(u.q,3),esc(u.reason)]))}`:''}
  ${p.newItems.length?`<h3>آیتم‌های جدید — در منو نیستند (${fa(p.newItems.length)})</h3><p class="muted" style="font-size:12px">${p.onlineStatus==='ok'?'قیمت و دستهٔ پیشنهادی از منوی آنلاین آمده است؛ قبل از ثبت بررسی کنید.':'منوی آنلاین در دسترس نبود؛ قیمت را دستی وارد کنید.'} رسپی را بعداً در «منو و قیمت» تعریف کنید؛ اولین رسپی هر آیتم از ابتدا معتبر است و مصرف همین فروش‌ها هم از انبار کم می‌شود.</p>${P.table(['افزودن','کد','نام','دسته',{t:'قیمت فروش',n:1},{t:'تعداد',n:1}],p.newItems.map((n,i)=>[`<input type="checkbox" data-sn="${i}" ${n.conflict?'disabled':'checked'} aria-label="افزودن ${esc(n.name)}">`,esc(n.code),`<input class="input" data-snn="${i}" value="${esc(n.name)}">${n.online?`<small class="muted" style="display:block">منوی آنلاین: ${esc(n.online.title)} — ${P.t(n.online.priceToman)}</small>`:''}`,`<select class="select" data-snc="${i}">${cats.map(c=>`<option ${c===n.category?'selected':''}>${esc(c)}</option>`).join('')}</select>`,`<input class="input num" data-snp="${i}" value="${n.priceToman?P.t(n.priceToman):''}" placeholder="الزامی" inputmode="numeric" style="width:120px">`,q(n.quantity,3)+(n.conflict?' '+P.b('بازهٔ تکراری','warning'):'')]))}`:''}
  <h3>اقلام قابل ثبت</h3>${P.table([...(p.hasDate?['تاریخ']:[]),'در فایل','آیتم منو',{t:'تعداد',n:1},{t:'مبلغ',n:1}],lines.slice(0,400).map(l=>{const m=menu.get(l.menuItemId);return[...(p.hasDate?[fa(l.from)]:[]),esc(`${l.sourceCode} | ${l.sourceName}`),`${esc(m?.name||l.menuItemId)}${l.matchedBy==='name'?' '+P.b('تطبیق با نام','warning'):''}`,q(l.quantity,3),T(l.saleAmountToman)]}),{empty:'هیچ ردیف قابل ثبتی پیدا نشد'})}`,
  onSave:(m,btn)=>{if(blocked)throw Error('این فایل قابل ثبت نیست؛ پیام‌های بالا را ببینید');const picks=p.newItems.map((n,i)=>({n,i})).filter(({i})=>m.querySelector(`[data-sn="${i}"]`)?.checked).map(({n,i})=>({code:n.code,name:m.querySelector(`[data-snn="${i}"]`).value.trim(),category:m.querySelector(`[data-snc="${i}"]`).value,price:P.num(m.querySelector(`[data-snp="${i}"]`).value),online:n.online}));
   for(const x of picks){if(!x.name)throw Error(`نام آیتم جدید با کد ${x.code} الزامی است`);if(!(x.price>0))throw Error(`قیمت فروش «${x.name}» را وارد کنید`)}
   const label=btn.innerHTML;btn.disabled=true;btn.innerHTML=P.ic('loader')+'ذخیره و تأیید روی سرور…';RT.icons();
   (async()=>{try{let created=[];if(picks.length){const {out,doc}=await W.edit(ioPricing,{action:'MENU_ITEMS_ADDED_FROM_SALES',details:{file:p.fileName},mutate:(d,c)=>SW.addMenuItems(d,c,{picks,fileName:p.fileName})});created=out;IC.attach({...raw(),pricing:doc,source:'live'})}
     p.createdIds=created.map(x=>x.id);const {out,doc}=await W.edit(io,{action:'SALES_EXCEL_IMPORTED',details:{file:p.fileName},mutate:(d,c)=>SW.addSales(d,c,{p,pricing:raw().pricing})});IC.attach({...raw(),inventory:doc,source:'live'});salesPrev=null;P.close();P.render();
     P.toast(`فروش ${SW.sourceLabel(p.source)} ثبت شد: ${fa(out.added.reduce((a,x)=>a+x.lines.length,0))} آیتم${created.length?`؛ ${fa(created.length)} آیتم جدید به منو اضافه شد (رسپی را تعریف کنید)`:''}${out.unmatched+out.newLeft?`؛ ${fa(out.unmatched+out.newLeft)} ردیف ثبت نشد`:''}`,'check')}
    catch(e){const el=document.getElementById('iwErr');if(el)el.textContent=e.message;P.toast(e.message,'alert-triangle');if(W.state.uncertain){P.close();P.render()}}finally{if(document.body.contains(btn)){btn.disabled=false;btn.innerHTML=label;RT.icons()}}})()}})}
function voidSalesForm(id){const sp=A(raw().inventory.salesPeriods).find(x=>x.id===id);if(!sp)return;
 formModal({title:'ابطال سند فروش',ok:'ابطال روی سرور',body:`<div class="sum-box"><span>${esc(SW.sourceLabel(SW.sourceOf(sp)))} · ${fa(E.D(sp.from||sp.date))}${sp.to&&sp.to!==sp.from?' تا '+fa(E.D(sp.to)):''}</span><b>${fa(A(sp.lines).length)} آیتم</b></div>${P.field('علت ابطال','<textarea class="textarea" name="reason" rows="2"></textarea>')}${P.note('سند حذف نمی‌شود؛ ابطال‌شده می‌ماند و مصرف رسپی آن از موجودی برمی‌گردد. برای اصلاح، فایل درست را دوباره وارد کنید.','info')}`,
  onSave:(m,b)=>{if(!canVoid())throw Error('ابطال فقط برای کاربر دارای دسترسی «ویرایش، ابطال و بازگردانی ثبت‌های انبار» مجاز است');const reason=val(m,'reason');run(b,{action:'SALES_PERIOD_VOIDED',details:{entityId:id},mutate:(d,c)=>SW.voidSales(d,c,{id,reason}),done:()=>'سند فروش ابطال شد'})}})}

/* ---------- daily beverage control (stage 11): the shared table of the current panel (core/js/beverage-control.js) ---------- */
const BEV=()=>window.RayoBeverageControl;
function bevItems(){const ids=A(raw().inventory?.settings?.beverageControl?.itemIds);return ids.map(id=>M().ing.get(id)).filter(Boolean).map(i=>({id:i.id,name:i.name,unit:i.recipeUnit||'عدد'}))}
function bevCfg(){return{title:'',autoRoles:false,items:bevItems,people:()=>A(window.PeopleReal?.doc?.()?.personnel).filter(p=>p.status==='فعال').map(p=>({id:p.id,name:p.name})),
 load:()=>io.load(),onLoaded:()=>{},
 // same save as the gateway: token + time, POST, then the table compares the reloaded lines (savedMatches)
 save:async d=>{d.meta=d.meta&&typeof d.meta==='object'?d.meta:{};d.meta.serverSaveToken=`INVENTORY-${Date.now()}-${Math.random().toString(36).slice(2,10)}`;d.meta.updatedAt=new Date().toISOString();await io.save(d);return io.load()},
 onSaved:d=>{IC.attach({...raw(),inventory:d,source:'live'});setTimeout(()=>{const h=document.getElementById('rvHost');if(h)IC.render('bev',h,()=>P.go('#/inventory/reports'))},0)},
 actor:()=>({type:'admin',personnelId:'',name:ses('rayo_admin_user')}),canEdit:()=>'',toast:(m,e)=>P.toast(m,e?'alert-triangle':'check'),confirm:m=>Promise.resolve(window.confirm(m))}}
function bevReal(){const items=bevItems();return srcLine()+(canWrite()?(items.length?P.card({title:'ثبت کنترل روزانهٔ نوشیدنی',sub:'همان جدول پنل فعلی و پنل پرسنل؛ خانهٔ خالی یعنی «وارد نشده» و نبودِ کالا را «۰» بنویسید',flush:1,body:'<div id="bevEntry" style="padding:var(--s3)"></div>'}):P.note('فهرست نوشیدنی‌های کنترل روزانه تعریف نشده است؛ در «تنظیمات» انبار انتخاب کنید.','info')):'')+'<div class="mt" id="rvHost"></div>'}
function bevMount(root){const h=P.$('#bevEntry',root);if(h&&BEV()?.table){if(!window.PeopleReal?.doc?.())window.PeopleReal?.load?.();h.innerHTML=BEV().table.html(bevCfg())}IC.render('bev',P.$('#rvHost',root),()=>P.go('#/inventory/reports'))}

/* ---------- inventory settings (stage 11): control levels, fryer oil, reorder points ---------- */
const LEVEL_LABEL={LIGHT:'سبک — از آخرین شمارش خودش ادامه می‌دهد',PRECISE:'دقیق — در هر شمارش کل شمرده شود',PARKED:'کنارگذاشته — بیرون از شمارش و هشدار'};
let stQ='';
function settingsReal(){const inv=raw().inventory,w=canWrite(),items=stockList(),fo=W.oilSettings(inv,raw().pricing),tableIds=new Set(A(inv.settings?.tableItems)),cnt=k=>items.filter(i=>W.levelOf(inv,i.id)===k).length,dis=w?'':'disabled';
 return srcLine()+`<div class="grid grid-2">${P.card({title:'سرخ‌کن‌ها و روغن',sub:'تعویض روغن به‌عنوان مصرف مجاز ثبت می‌شود؛ از تاریخ شروع دفتر، روغن سرخ‌کردنی از رسپی‌ها کم نمی‌شود',actions:w?`<button class="btn btn-primary btn-sm" id="stFrySave">${P.ic('save')}ذخیره</button>`:'',body:`<div class="form-grid">${P.field('قلم روغن سرخ‌کردنی',`<select class="select" id="stOil" ${dis}>${items.map(i=>`<option value="${esc(i.id)}" ${i.id===fo.ingredientId?'selected':''}>${esc(itemLabel(i))}</option>`).join('')}</select>`)}${P.field('چگالی (کیلو بر لیتر)',`<input class="input num" id="stDensity" value="${fa(fo.density)}" ${dis}>`)}${P.field('شروع دفتر تعویض',`<input class="input num" id="stLogFrom" value="${fa(fo.logFrom||'')}" placeholder="خالی = هنوز از رسپی کم می‌شود" ${dis}>`)}</div>
  <div id="stFryers" class="stack mt" style="gap:6px">${fo.fryers.map(f=>`<div class="row st-fry" style="gap:6px"><input class="input" data-fid="${esc(f.id)}" value="${esc(f.name)}" placeholder="نام" ${dis}><input class="input num" style="width:110px" value="${fa(f.liters)}" placeholder="لیتر" ${dis}>${w?`<button type="button" class="btn btn-ghost btn-sm btn-icon" data-frdel aria-label="حذف">${P.ic('x')}</button>`:''}</div>`).join('')}</div>${w?`<button type="button" class="btn btn-ghost btn-sm mt" id="stFryAdd">${P.ic('plus')}سرخ‌کن</button>`:''}
  ${P.field('اقلام سر میز (روغن زیتون، سس‌ها…) — کنترل با استاندارد مصرف',`<div class="row" style="flex-wrap:wrap;gap:6px;max-height:160px;overflow:auto" id="stTable">${items.filter(i=>tableIds.has(i.id)||/زیتون|سس|کچاپ|مایونز|خردل|نمک|فلفل/.test(i.name)).map(i=>`<label class="check"><input type="checkbox" value="${esc(i.id)}" ${tableIds.has(i.id)?'checked':''} ${dis}>${esc(i.name)}</label>`).join('')}</div>`)}`})}
  ${P.card({title:'سطح کنترل اقلام در شمارش',sub:`سبک ${fa(cnt('LIGHT'))} · دقیق ${fa(cnt('PRECISE'))} · کنارگذاشته ${fa(cnt('PARKED'))}`,actions:w?`<button class="btn btn-primary btn-sm" id="stLvlSave">${P.ic('save')}ذخیره</button>`:'',body:`<div class="form-grid">${P.field('جستجو',`<input class="input" id="stQ" value="${esc(stQ)}" placeholder="نام یا کد">`)}${P.field('حداکثر فاصلهٔ شمارش اقلام سبک (روز)',`<input class="input num" id="stGap" value="${fa(Number(inv.settings?.lightMaxGapDays)||90)}" ${dis}>`)}</div><div id="stLevels" style="max-height:340px;overflow:auto" class="mt">${P.table(['کالا','سطح'],items.map(i=>({attr:`data-lv-row data-k="${esc(`${i.name} ${i.code}`)}"`,c:[esc(itemLabel(i)),`<select class="select" data-lv="${esc(i.id)}" ${dis}>${W.LEVELS.map(k=>`<option value="${k}" ${W.levelOf(inv,i.id)===k?'selected':''}>${LEVEL_LABEL[k]}</option>`).join('')}</select>`]})))}</div>`})}</div>
 <div class="mt">${P.card({title:'نقطهٔ سفارش و موجودی هدف',sub:'روی خود قلم (کاتالوگ) ذخیره می‌شود و در «سفارش مجدد» به کار می‌رود؛ خالی یعنی تعریف نشده',actions:w?`<button class="btn btn-primary btn-sm" id="stRpSave">${P.ic('save')}ذخیره</button>`:'',flush:1,body:`<div id="stRp" style="max-height:420px;overflow:auto">${P.table(['کالا','واحد',{t:'موجودی امروز',n:1},{t:'نقطهٔ سفارش',n:1},{t:'موجودی هدف',n:1}],pos().filter(r=>items.some(i=>i.id===r.id)).sort((a,b)=>(b.hasReorderPoint-a.hasReorderPoint)||String(a.name).localeCompare(String(b.name),'fa')).map(r=>{const i=M().ing.get(r.id);return{attr:`data-rp-row data-k="${esc(`${r.name} ${r.code}`)}"`,c:[esc(r.name),esc(r.unit),q(r.qty),`<input class="input num" style="width:100px" data-rp="${esc(r.id)}" value="${i?.reorderPoint!==undefined&&i?.reorderPoint!==null&&i?.reorderPoint!==''?fa(i.reorderPoint):''}" ${dis}>`,`<input class="input num" style="width:100px" data-ts="${esc(r.id)}" value="${i?.targetStock!==undefined&&i?.targetStock!==null&&i?.targetStock!==''?fa(i.targetStock):''}" ${dis}>`]}}))}</div>`})}</div>
 <div class="grid grid-2 mt">${bevSettingsCard(w)}${zeroCard(w)}</div>`}
/* daily beverage control items: checked items in their saved order, then the rest by name */
function bevSettingsCard(w){const sel=A(raw().inventory?.settings?.beverageControl?.itemIds),items=stockList().slice().sort((a,b)=>(sel.includes(b.id)-sel.includes(a.id))||(sel.indexOf(a.id)-sel.indexOf(b.id))||a.name.localeCompare(b.name,'fa'));
 return P.card({title:'نوشیدنی‌های کنترل روزانه',sub:`${fa(sel.length)} قلم؛ هر روز در یخچال‌های سالن شمرده می‌شوند (پنل جدید، پنل فعلی و پنل پرسنل). ترتیب فرم، ترتیب انتخاب است`,actions:w?`<button class="btn btn-secondary btn-sm" id="stBevCorp">${P.ic('cup-soda')}نوشابه و آب معدنی</button><button class="btn btn-primary btn-sm" id="stBevSave">${P.ic('save')}ذخیره</button>`:'',
  body:`${P.field('جستجو','<input class="input" id="stBevQ" placeholder="نام یا گروه">')}<div id="stBev" class="stack" style="gap:2px;max-height:300px;overflow:auto">${items.map(i=>`<label class="check" data-bev-row data-k="${esc(i.name+' '+(i.category||''))}"><input type="checkbox" value="${esc(i.id)}" ${sel.includes(i.id)?'checked':''} ${w?'':'disabled'}>${esc(i.name)} <small class="muted">${esc(i.category||'')}</small></label>`).join('')}</div>`})}
/* zero for items never counted (and «دقیق» items missing) in the latest baseline: preview, backup, apply, rollback */
function zeroCard(w){const last=W.lastZeroFill(raw().inventory);return P.card({title:'صفر برای اقلام شمارش‌نشده',sub:'برای شروع انبارداری یا بعد از شمارش کامل',
  body:`${P.note('اقلامی که هرگز در هیچ شمارش کلی نبوده‌اند و اقلام «دقیق» که در این مبنا شمرده نشده‌اند، با مقدار صفر (شمرده شد و نیست) به مبنای همان تاریخ اضافه می‌شوند. اقلام «سبک» شمرده‌شده از شمارش قبلی خودشان ادامه می‌دهند. اگر قلمی موجود بوده ولی شمرده نشده، صفر گرفتن آن مانده را منفی می‌کند. فقط روی آخرین مبنا ممکن است.','alert-triangle')}
  <div class="form-grid">${P.field('تاریخ مبنا',`<input class="input" id="stZDate" value="${esc(E.CAL.today)}" ${w?'':'disabled'}>`)}${P.field('زمان مبنا',`<select class="select" id="stZB" ${w?'':'disabled'}><option value="END">پایان روز</option><option value="START">ابتدای روز (افتتاحیه)</option></select>`)}</div>
  ${w?`<div class="row mt" style="gap:8px;flex-wrap:wrap"><button class="btn btn-secondary" id="stZPrev">${P.ic('eye')}پیش‌نمایش</button>${last?`<button class="btn btn-ghost" id="stZBack">${P.ic('undo-2')}بازگردانی آخرین صفرگذاری (${fa(E.D(last.date)||'')})</button>`:''}</div>`:''}`})}
/* backup = the server copy of the inventory module, downloaded before a structural change */
async function backupDownload(btn){const doc=await io.load(),blob=new Blob([JSON.stringify(doc,null,1)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`rayo-inventory-backup-${E.CAL.today.replace(/\//g,'-')}-${Date.now()}.json`;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500);return true}
function structuralModal({title,desc,rows,ok,action,details,mutate,done}){let backed=false;
 formModal({title,ok,size:'wide',body:`${P.note(desc,'alert-triangle')}${P.table(['قلم','کد','واحد',{t:'مقدار',n:1}],rows.map(r=>[esc(r.name),esc(r.code||''),esc(r.unit||''),fa(0)]),{empty:'موردی نیست'})}
  <div class="row mt" style="gap:8px;flex-wrap:wrap;align-items:center"><button type="button" class="btn btn-secondary" id="stBk">${P.ic('download')}دانلود پشتیبان انبار</button><span class="muted" id="stBkS">پیش از اجرا لازم است</span></div>`,
  onMount:m=>{P.$('#stBk',m).onclick=async e=>{const b=e.currentTarget;b.disabled=true;try{await backupDownload();backed=true;P.$('#stBkS',m).textContent='پشتیبان دانلود شد'}catch(x){P.toast(x.message||String(x),'alert-triangle')}finally{b.disabled=false}}},
  onSave:(m,btn)=>{if(!backed)throw Error('ابتدا پشتیبان انبار را دانلود کنید');if(!confirm(title+' اجرا شود؟'))return;run(btn,{action,details,mutate,done})}})}
function settingsMount(root){const filter=()=>{const v=stQ.toLowerCase();for(const r of root.querySelectorAll('[data-lv-row],[data-rp-row]'))r.style.display=!v||P.match(r.dataset.k,v)?'':'none'};const sq=P.$('#stQ',root);if(sq){sq.oninput=e=>{stQ=e.target.value;filter()};filter()}
 const num=v=>IE_NUM(v);
 const fa1=P.$('#stFryAdd',root);if(fa1)fa1.onclick=()=>{P.$('#stFryers',root).insertAdjacentHTML('beforeend',`<div class="row st-fry" style="gap:6px"><input class="input" placeholder="نام"><input class="input num" style="width:110px" placeholder="لیتر"><button type="button" class="btn btn-ghost btn-sm btn-icon" data-frdel aria-label="حذف">${P.ic('x')}</button></div>`);RT.icons()};
 P.$('#stFryers',root)?.addEventListener('click',e=>{const b=e.target.closest('[data-frdel]');if(b)b.closest('.st-fry').remove()});
 const fs=P.$('#stFrySave',root);if(fs)fs.onclick=()=>{const input={ingredientId:P.$('#stOil',root).value,density:latin(P.$('#stDensity',root).value).replace(/٫/g,'.'),logFrom:latin(P.$('#stLogFrom',root).value),fryers:[...root.querySelectorAll('.st-fry')].map(r=>{const [n,l]=r.querySelectorAll('input');return{id:n.dataset.fid||'',name:n.value.trim(),liters:latin(l.value).replace(/٫/g,'.')}}),tableItems:[...root.querySelectorAll('#stTable input:checked')].map(x=>x.value)};
  try{W.saveFryerSettings(JSON.parse(JSON.stringify(raw().inventory)),{pricing:raw().pricing,at:'',actor:''},input)}catch(e){return P.toast(e.message,'alert-triangle')}run(fs,{action:'FRYER_OIL_SETTINGS_CHANGED',details:{fryers:input.fryers.length},mutate:(d,c)=>W.saveFryerSettings(d,c,input),done:()=>'تنظیمات سرخ‌کن ذخیره شد'})};
 const ls=P.$('#stLvlSave',root);if(ls)ls.onclick=()=>{const levels={};for(const s of root.querySelectorAll('[data-lv]'))levels[s.dataset.lv]=s.value;const gap=latin(P.$('#stGap',root).value);run(ls,{action:'ITEM_CONTROL_LEVELS_CHANGED',details:{},mutate:(d,c)=>W.saveControlLevels(d,c,{levels,gap}),done:o=>`سطح کنترل ${fa(o.changes)} قلم ذخیره شد`})};
 const bq=P.$('#stBevQ',root);if(bq)bq.oninput=e=>{const v=e.target.value;for(const r of root.querySelectorAll('[data-bev-row]'))r.style.display=!v||P.match(r.dataset.k,v)?'':'none'};
 const bc=P.$('#stBevCorp',root);if(bc)bc.onclick=()=>{let n=0;for(const r of root.querySelectorAll('[data-bev-row]')){const c=r.querySelector('input');if(/کوکا|فانتا|اسپرایت|زیرو|نوشابه|آب\s*معدنی|سون\s*آپ|پپسی|میراندا/.test(r.dataset.k)&&!c.checked){c.checked=true;n++}}P.toast(n?`${fa(n)} قلم انتخاب شد؛ برای اعمال «ذخیره» را بزنید`:'قلم تازه‌ای پیدا نشد','cup-soda')};
 const bs=P.$('#stBevSave',root);if(bs)bs.onclick=()=>{const itemIds=[...root.querySelectorAll('[data-bev-row] input:checked')].map(x=>x.value);run(bs,{action:'BEVERAGE_CONTROL_ITEMS_CHANGED',details:{count:itemIds.length},mutate:(d,c)=>W.saveBeverageItems(d,c,{itemIds}),done:o=>`فهرست نوشیدنی‌ها ذخیره شد (${fa(o.count)} قلم)`})};
 const zp=P.$('#stZPrev',root);if(zp)zp.onclick=()=>{const input={date:E.D(latin(P.$('#stZDate',root).value)),boundary:P.$('#stZB',root).value};let p;try{p=W.zeroFillPlan(raw().inventory,raw().pricing,input)}catch(e){return P.toast(e.message,'alert-triangle')}if(!p.items.length)return P.toast('همهٔ اقلام در این مبنا شمرده شده‌اند؛ چیزی برای صفرگذاری نیست','info');
  structuralModal({title:`صفرگذاری ${fa(p.items.length)} قلم در مبنای ${fa(p.date)}`,desc:`این اقلام با مقدار صفر به ${p.target?'شمارش موجود همین تاریخ':'یک شمارش تازه'} (${p.boundary==='START'?'ابتدای روز':'پایان روز'}) اضافه می‌شوند. با «بازگردانی آخرین صفرگذاری» برمی‌گردد.`,rows:p.items.map(i=>({name:i.name,code:i.code,unit:W.unitName(i)})),ok:'صفرگذاری روی سرور',action:'INVENTORY_ZERO_FILLED',details:{},mutate:(d,c)=>W.zeroFill(d,c,input),done:o=>`${fa(o.count)} قلم صفر ثبت شد`})};
 const zb=P.$('#stZBack',root);if(zb)zb.onclick=()=>{let p;try{p=W.zeroFillRollbackPlan(raw().inventory)}catch(e){return P.toast(e.message,'alert-triangle')}
  structuralModal({title:'بازگردانی آخرین صفرگذاری',desc:p.entry.createdId?'شمارشی که صفرگذاری ساخته بود باطل می‌شود (حذف نمی‌شود).':'فقط ردیف‌های صفرِ افزوده‌شده از شمارش برداشته می‌شوند.',rows:p.lines.map(l=>({name:l.itemNameSnapshot,code:l.itemCodeSnapshot,unit:l.unitSnapshot})),ok:'بازگردانی روی سرور',action:'INVENTORY_ZERO_FILL_ROLLED_BACK',details:{},mutate:(d,c)=>W.zeroFillRollback(d,c),done:o=>`صفرگذاری ${fa(o.count)} قلم برگشت`})};
 const rs=P.$('#stRpSave',root);if(rs)rs.onclick=()=>{const rows={};for(const x of root.querySelectorAll('[data-rp]'))rows[x.dataset.rp]={reorderPoint:latin(x.value).replace(/٫/g,'.').replace(/[٬,]/g,''),targetStock:latin(root.querySelector(`[data-ts="${x.dataset.rp}"]`).value).replace(/٫/g,'.').replace(/[٬,]/g,'')};
  run(rs,{action:'REORDER_POINTS_CHANGED',details:{},io:ioPricing,apply:doc=>IC.attach({...raw(),pricing:doc,source:'live'}),mutate:(d,c)=>W.saveReorderPoints(d,c,{rows}),done:n=>`نقطهٔ سفارش ${fa(n)} قلم ذخیره شد`})}}
const IE_NUM=v=>Number(latin(v).replace(/٫/g,'.').replace(/[٬,]/g,''));

/* explicit manager action: re-derive the variance of every whole count (open periods) from the current data, e.g. after
   recipe or price changes in the menu module, which do not pass through an inventory save */
function recalcAll(){if(!canWrite())return P.toast(whyLocked(),'lock');
 formModal({title:'بازمحاسبهٔ مغایرت همهٔ شمارش‌ها',ok:'بازمحاسبه و ذخیره',body:P.note('مورد انتظار و مغایرت هر شمارش کل (به‌جز افتتاحیه و دورهٔ بسته) با دادهٔ فعلی انبار و رسپی‌ها دوباره حساب می‌شود. مقدار قبلی هر ردیف در سابقهٔ همان شمارش می‌ماند و بررسی ردیف تغییرکرده دوباره باز می‌شود. ثبت‌های انبار از پنل جدید این کار را خودکار انجام می‌دهند؛ این دکمه برای تغییر رسپی یا ثبت‌های پنل پرسنل و نسخهٔ قدیمی است.','info'),
  onSave:(m,btn)=>run(btn,{action:'COUNT_VARIANCE_RECALCULATED_ALL',details:{},ioOpts:{recalcAll:true},mutate:()=>({}),done:o=>o.recalculated?'بازمحاسبه انجام شد':'مغایرت شمارش‌ها با دادهٔ فعلی تغییری نداشت'})})}
window.InvEntry={receipt:receiptForm,event:eventForm,oil:oilForm,count:countForm,void:voidForm,recalcAll,canWrite,canVoid,
 // shared with menu-real.js
 formModal,run,allowed,live,ses,dataList,latin};

/* ---------- wiring: real view when connected, sample + hint otherwise ---------- */
const hint=()=>P.note(`این صفحه <b>دادهٔ نمونه</b> است. برای دیدن دادهٔ واقعی، در «داشبورد کنترل» به دادهٔ انبار وصل شوید. <a href="#/inventory/control">اتصال</a>`,'database');
const viaIC=view=>({render:()=>srcLine()+'<div id="rvHost"></div>',mount:root=>IC.render(view,P.$('#rvHost',root),v=>P.go('#/inventory/reports'))});
const REAL={stock:{render:stockReal,mount:stockMount},receipt:{render:receiptReal,mount:voidMount},waste:{render:wasteReal,mount:voidMount},count:viaIC('counts'),beverage:{render:bevReal,mount:bevMount},reorder:{render:reorderReal},sales:{render:salesReal,mount:salesMount},consumption:viaIC('oil'),catalog:{render:catalogReal},settings:{render:settingsReal,mount:settingsMount}};
const btn=(icon,label,fn,secondary)=>canWrite()?`<button class="btn ${secondary?'btn-secondary':'btn-primary'}" onclick="${fn}">${P.ic(icon)}${label}</button>`:`<button class="btn btn-secondary" disabled title="${esc(whyLocked())}">${P.ic('lock')}${label}</button>`;
const ACTIONS={receipt:()=>btn('package-plus','ثبت ورود','InvEntry.receipt()'),waste:()=>btn('droplet','تعویض روغن','InvEntry.oil()',1)+btn('trash-2','ثبت پرتی / مصرف','InvEntry.event()'),count:()=>btn('refresh-cw','بازمحاسبهٔ مغایرت‌ها','InvEntry.recalcAll()',1)+btn('clipboard-list','ثبت شمارش','InvEntry.count()')};
for(const [id,v] of Object.entries(REAL)){const t=inv.tabs.find(x=>x.id===id);if(!t)continue;const r0=t.render,m0=t.mount,a0=t.actions;
 t.render=r=>IC.ready()?v.render(r):hint()+r0(r);
 t.mount=(root,r)=>{if(IC.ready()){v.mount&&v.mount(root,r)}else m0&&m0(root,r)};
 // sales, beverage and settings have their entry controls inside the page
 if(a0||ACTIONS[id])t.actions=r=>IC.ready()?(ACTIONS[id]?ACTIONS[id]():['sales','beverage','settings'].includes(id)?'':`<a class="btn btn-secondary" href="#/inventory/legacy">${P.ic('external-link')}ثبت در پنل فعلی</a>`):(a0?a0(r):'');}
/* stock tab badge = items needing order (real) */
const ro=inv.tabs.find(x=>x.id==='reorder');if(ro){const b0=ro.badge;ro.badge=()=>IC.ready()?pos().filter(r=>r.needOrder).length:(b0?b0():0)}
const st=inv.tabs.find(x=>x.id==='stock');if(st)st.badge=()=>IC.ready()?pos().filter(r=>r.needOrder).length:0;
inv.badge=()=>IC.ready()?pos().filter(r=>r.flags.has('negative')).length:D.ITEMS.filter(i=>i.qty<i.min).length;
})();
